#!/usr/bin/env python3
"""Converts CoordgenTemplates.cpp of coordgenlibs 3.0.2 (the autogenerated ring system templates) to the text data file
crates/rdoxide/src/external/coordgen/data/templates.txt:  T <natoms> <nbonds>, then "<Z> <x> <y>" and "<a> <b> <order>" lines.

    python3 tools/gen_coordgen_templates.py coordgenlibs-3.0.2/CoordgenTemplates.cpp > crates/rdoxide/src/external/coordgen/data/templates.txt
"""
import re
import sys

text = open(sys.argv[1]).read()
blocks = text.split("auto molecule = new sketcherMinimizerMolecule();")[1:]
out = []
for b in blocks:
    atoms = re.findall(r"tuple<int, float, float>\((\d+), (-?[\d.]+)f, (-?[\d.]+)f\)", b)
    bonds = re.findall(r"\{ (\d+), (\d+), (\d+) \}", b)
    na = int(re.search(r"std::array<std::tuple<int, float, float>, (\d+)>", b).group(1))
    nb = int(re.search(r"std::array<std::array<int, 3>, (\d+)>", b).group(1))
    assert len(atoms) == na and len(bonds) == nb, (len(atoms), na, len(bonds), nb)
    out.append("T %d %d" % (na, nb))
    out += ["%s %s %s" % a for a in atoms]
    out += ["%s %s %s" % a for a in bonds]
print("\n".join(out))
